1	/**
2	 * @copyright
3	 * Copyright 2025 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b neon_rot_ldr_at_top_rowmajor_sve
7	 * @parblock
8	 * SVE port of neon_rot_ldr_at_top_rowmajor (microarchitecture-dimension
9	 * variant of the position probe, 2026-09-08): the 55-record dump campaign
10	 * showed corruption concentrated on the FIRST indices of the inner loop
11	 * (idx 0 + idx 1 = 36/55 records) while the buffer spans 1024 entries.
12	 * This variant walks the 1024 vector slots in a REVISED order — even
13	 * outer iterations sweep ascending, odd outer iterations descending — so
14	 * the touch pattern at idx 0/1 differs (on a descending pass, index 0 is
15	 * the LAST slot touched, with a fully-warm pipeline behind it, and the
16	 * store->load adjacency across the loop seam changes).
17	 *   strong idx-0/1 signal also here -> the signature follows the buffer
18	 *      slots themselves (address-local, e.g. same L1D set/way)
19	 *   signature moves to the sweep seam / disappears ->
20	 *      it follows the forward-progress position in the sweep
21	 * Same skeleton as the parent otherwise: 3rd ldr (scratch, discarded) at
22	 * top + 2-source ldr z loads + rotating svadd/sveor/svand/svorr per slot
23	 * (slot%4) + back-to-back str temp / str dst; memcmp in the cold path.
24	 * @endparblock
25	 */
26	
27	#include "sandstone.h"
28	#include <cstdint>
29	#include <cstring>
30	#include <cstdlib>
31	
32	#if defined(__aarch64__)
33	#include <arm_sve.h>
34	#include <sys/auxv.h>
35	
36	#ifndef HWCAP_SVE
37	#define HWCAP_SVE (1 << 22)
38	#endif
39	#endif
40	
41	#define NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS 1024
42	
43	struct NeonRotLdrAtTopRowMajorSveData {
44	    uint64_t *srcA;
45	    uint64_t *srcB;
46	    uint64_t *scratch;
47	    uint64_t *expected;
48	    int lanes;
49	};
50	
51	#if defined(__aarch64__)
52	
53	static inline void store_vec_sve(void *addr, svuint64_t val) {
54	    svst1_u64(svptrue_b64(), static_cast<uint64_t *>(addr), val);
55	}
56	
57	static inline svuint64_t load_vec_sve(const void *addr) {
58	    svuint64_t res;
59	    __asm__ volatile ("ldr %0, [%1]" : "=w"(res) : "r"(addr) : "memory");
60	    return res;
61	}
62	
63	#endif
64	
65	static int neon_rot_ldr_at_top_rowmajor_sve_init(struct test *test) {
66	#if defined(__aarch64__)
67	    unsigned long hwcap = getauxval(AT_HWCAP);
68	    if ((hwcap & HWCAP_SVE) == 0) {
69	        log_skip(CpuNotSupportedSkipCategory,
70	                 "to be implemented (placeholder): ARM SVE required for neon_rot_ldr_at_top_rowmajor_sve");
71	        return EXIT_SKIP;
72	    }
73	
74	    const int lanes = (int)svcntd();
75	    const size_t elems = (size_t)NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS * lanes;
76	
77	    auto *data = static_cast<NeonRotLdrAtTopRowMajorSveData *>(malloc(sizeof(NeonRotLdrAtTopRowMajorSveData)));
78	    data->lanes = lanes;
79	    data->srcA = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
80	    data->srcB = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
81	    data->scratch = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
82	    data->expected = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
83	
84	    memset_random(data->srcA, elems * sizeof(uint64_t));
85	    memset_random(data->srcB, elems * sizeof(uint64_t));
86	    memset_random(data->scratch, elems * sizeof(uint64_t));
87	
88	    /* golden: same rotating composition per slot (slot%4, whole vector), computed on the same SVE units */
89	    svbool_t pg = svptrue_b64();
90	    for (int i = 0; i < NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS; i++) {
91	        svuint64_t a = svld1_u64(pg, data->srcA + (size_t)i * lanes);
92	        svuint64_t b = svld1_u64(pg, data->srcB + (size_t)i * lanes);
93	        svuint64_t res;
94	        switch (i % 4) {
95	            case 0: res = svadd_u64_x(pg, a, b); break;
96	            case 1: res = sveor_u64_x(pg, a, b); break;
97	            case 2: res = svand_u64_x(pg, a, b); break;
98	            case 3: res = svorr_u64_x(pg, a, b); break;
99	        }
100	        svst1_u64(pg, data->expected + (size_t)i * lanes, res);
101	    }
102	
103	    test->data = data;
104	    return EXIT_SUCCESS;
105	#else
106	    (void)test;
107	    log_skip(CpuNotSupportedSkipCategory,
108	             "to be implemented (placeholder): ARM SVE required for neon_rot_ldr_at_top_rowmajor_sve");
109	    return EXIT_SKIP;
110	#endif
111	}
112	
113	#if defined(__aarch64__)
114	static int neon_rot_ldr_at_top_rowmajor_sve_run(struct test *test, int cpu) {
115	    (void)cpu;
116	    auto *data = static_cast<NeonRotLdrAtTopRowMajorSveData *>(test->data);
117	
118	    /* 共享缓冲按 init 时的 VL 定容；线程继承同 VL，但失配会导致静默错位
119	     * (假 SDC)，fail-closed 显式报错 */
120	    if ((int)svcntd() != data->lanes) {
121	        log_error("neon_rot_ldr_at_top_rowmajor_sve: vector length changed between init (%d) and run (%d)",
122	                  data->lanes, (int)svcntd());
123	        report_fail_msg("neon_rot_ldr_at_top_rowmajor_sve: vector length changed between init and run");
124	    }
125	
126	    const size_t elems = (size_t)NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS * data->lanes;
127	    uint64_t *temp = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
128	    uint64_t *dst  = static_cast<uint64_t *>(aligned_alloc(64, elems * sizeof(uint64_t)));
129	
130	    uint64_t sweep = 0;
131	    TEST_LOOP(test, 1 << 13) {
132	        const bool ascending = (sweep & 1) == 0;
133	        for (int n = 0; n < NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS; n++) {
134	            const int i = ascending ? n : (NEON_ROT_LDR_AT_TOP_ROWMAJOR_SVE_SLOTS - 1 - n);
135	            const size_t off = (size_t)i * data->lanes;
136	
137	            /* 3rd load at the TOP of the iteration (before the sources);
138	             * value intentionally discarded — this probe measures the
139	             * presence/position of the load, not its data */
140	            svuint64_t unused_x = load_vec_sve(data->scratch + off);
141	            (void)unused_x;
142	
143	            svuint64_t a = load_vec_sve(data->srcA + off);
144	            svuint64_t b = load_vec_sve(data->srcB + off);
145	            svuint64_t res;
146	
147	            switch (i % 4) {
148	                case 0: res = svadd_u64_x(svptrue_b64(), a, b); break;
149	                case 1: res = sveor_u64_x(svptrue_b64(), a, b); break;
150	                case 2: res = svand_u64_x(svptrue_b64(), a, b); break;
151	                case 3: res = svorr_u64_x(svptrue_b64(), a, b); break;
152	            }
153	
154	            /* both stores write the ALU result — the str temp / str dst
155	             * pair stays back-to-back with NO memory op in between */
156	            store_vec_sve(temp + off, res);
157	            store_vec_sve(dst + off, res);
158	        }
159	        sweep++;
160	
161	        if (memcmp(dst, data->expected, elems * sizeof(uint64_t)) != 0) {
162	            report_fail_msg("neon_rot_ldr_at_top_rowmajor_sve data miscompare");
163	        }
164	    }
165	
166	    free(dst);
167	    free(temp);
168	    return EXIT_SUCCESS;
169	}
170	#else
171	static int neon_rot_ldr_at_top_rowmajor_sve_run(struct test *test, int cpu) {
172	    (void)test; (void)cpu;
173	    log_skip(CpuNotSupportedSkipCategory,
174	             "to be implemented (placeholder): ARM SVE required for neon_rot_ldr_at_top_rowmajor_sve");
175	    return EXIT_SKIP;
176	}
177	#endif
178	
179	static int neon_rot_ldr_at_top_rowmajor_sve_cleanup(struct test *test) {
180	    auto *data = static_cast<NeonRotLdrAtTopRowMajorSveData *>(test->data);
181	    if (data) {
182	        free(data->srcA);
183	        free(data->srcB);
184	        free(data->scratch);
185	        free(data->expected);
186	        free(data);
187	    }
188	    return EXIT_SUCCESS;
189	}
190	
191	DECLARE_TEST(neon_rot_ldr_at_top_rowmajor_sve,
192	             "SVE datapath variant of the order probe: alternate ascending/descending "
193	             "sweeps over 1024 slots with 3rd ldr z at top + rotating ALU + "
194	             "back-to-back str pair (port of neon_rot_ldr_at_top_rowmajor)")
195	    .test_init    = neon_rot_ldr_at_top_rowmajor_sve_init,
196	    .test_run     = neon_rot_ldr_at_top_rowmajor_sve_run,
197	    .test_cleanup = neon_rot_ldr_at_top_rowmajor_sve_cleanup,
198	    .quality_level = TEST_QUALITY_PROD,
199	END_DECLARE_TEST
