1	/**
2	 * @copyright
3	 * Copyright 2022 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b neon_rot_u8x16
7	 * @parblock
8	 * NEON variant with 16-lane byte lanes (uint8x16_t) instead of 2-lane 64-bit
9	 * (uint64x2_t): same 16B per operand/instruction width, completely different
10	 * lane structure. Discriminates width-vs-lane hypotheses for the NEON firing
11	 * rate amplification (neon_rot_2src ~33 fail/30min = 1.7x scalar):
12	 *  - rate stays ~1.1/min  -> 16B op width is the amplifier (data-volume billing)
13	 *  - rate drops to ~0     -> the 2x64b lane structure is what matters
14	 *  - rate mid             -> mixed/interaction, needs follow-up
15	 * Op set is the byte-wise analogue of the rotation: {add (saturating? no —
16	 * plain wrapping via vaddq), eor, and, orr} on uint8x16. Skeleton otherwise
17	 * identical to neon_rot_2src.
18	 * @endparblock
19	 */
20	
21	#include "sandstone.h"
22	#include <cstdint>
23	#include <cstring>
24	
25	#if defined(__aarch64__)
26	#include <arm_neon.h>
27	#endif
28	
29	#define NEON_ROT_U8X16_COUNT 1024   /* uint8x16 elements -> 16KB per buffer */
30	
31	struct NeonRotU8x16Data {
32	    uint8x16_t *srcA;
33	    uint8x16_t *srcB;
34	    uint8x16_t *expected;
35	};
36	
37	#if defined(__aarch64__)
38	
39	/* store via NEON intrinsic (compiles to str q); reload via inline asm —
40	 * REQUIRED: objdump showed the compiler eliminates the intrinsic reload
41	 * (reuses the stored register for dst, no ldr emitted). The asm boundary
42	 * makes the back-to-back str q -> ldr q pair guaranteed in the binary. */
43	static inline void store_vec_u8(void *addr, uint8x16_t val) {
44	    vst1q_u8(static_cast<uint8_t *>(addr), val);
45	}
46	
47	static inline uint8x16_t load_vec_u8(const void *addr) {
48	    uint8x16_t res;
49	    __asm__ volatile ("ldr %q0, [%1]" : "=w"(res) : "r"(addr) : "memory");
50	    return res;
51	}
52	
53	#endif
54	
55	static int neon_rot_u8x16_init(struct test *test) {
56	    auto *data = static_cast<NeonRotU8x16Data *>(malloc(sizeof(NeonRotU8x16Data)));
57	    data->srcA = static_cast<uint8x16_t *>(aligned_alloc(64, NEON_ROT_U8X16_COUNT * sizeof(uint8x16_t)));
58	    data->srcB = static_cast<uint8x16_t *>(aligned_alloc(64, NEON_ROT_U8X16_COUNT * sizeof(uint8x16_t)));
59	    data->expected = static_cast<uint8x16_t *>(aligned_alloc(64, NEON_ROT_U8X16_COUNT * sizeof(uint8x16_t)));
60	
61	    memset_random(data->srcA, NEON_ROT_U8X16_COUNT * sizeof(uint8x16_t));
62	    memset_random(data->srcB, NEON_ROT_U8X16_COUNT * sizeof(uint8x16_t));
63	
64	    /* golden: same rotating composition, computed on the same NEON units */
65	    for (int i = 0; i < NEON_ROT_U8X16_COUNT; i++) {
66	        switch (i % 4) {
67	            case 0: data->expected[i] = vaddq_u8(data->srcA[i], data->srcB[i]); break;
68	            case 1: data->expected[i] = veorq_u8(data->srcA[i], data->srcB[i]); break;
69	            case 2: data->expected[i] = vandq_u8(data->srcA[i], data->srcB[i]); break;
70	            case 3: data->expected[i] = vorrq_u8(data->srcA[i], data->srcB[i]); break;
71	        }
72	    }
73	
74	    test->data = data;
75	    return EXIT_SUCCESS;
76	}
77	
78	static int neon_rot_u8x16_run(struct test *test, int cpu) {
79	    auto *data = static_cast<NeonRotU8x16Data *>(test->data);
80	
81	    uint8x16_t *temp = static_cast<uint8x16_t *>(aligned_alloc(64, NEON_ROT_U8X16_COUNT * sizeof(uint8x16_t)));
82	    uint8x16_t *dst  = static_cast<uint8x16_t *>(aligned_alloc(64, NEON_ROT_U8X16_COUNT * sizeof(uint8x16_t)));
83	
84	    TEST_LOOP(test, 1 << 13) {
85	        for (int i = 0; i < NEON_ROT_U8X16_COUNT; i++) {
86	            uint8x16_t a = load_vec_u8(&data->srcA[i]);
87	            uint8x16_t b = load_vec_u8(&data->srcB[i]);
88	            uint8x16_t res;
89	
90	            switch (i % 4) {
91	                case 0: res = vaddq_u8(a, b); break;
92	                case 1: res = veorq_u8(a, b); break;
93	                case 2: res = vandq_u8(a, b); break;
94	                case 3: res = vorrq_u8(a, b); break;
95	            }
96	
97	            store_vec_u8(&temp[i], res);
98	            store_vec_u8(&dst[i], load_vec_u8(&temp[i]));
99	        }
100	
101	        if (memcmp(dst, data->expected, NEON_ROT_U8X16_COUNT * sizeof(uint8x16_t)) != 0) {
102	            report_fail_msg("neon_rot_u8x16 data miscompare");
103	        }
104	    }
105	
106	    free(dst);
107	    free(temp);
108	    return EXIT_SUCCESS;
109	}
110	
111	static int neon_rot_u8x16_cleanup(struct test *test) {
112	    auto *NeonRotData = static_cast<NeonRotU8x16Data *>(test->data);
113	    auto *data = NeonRotData;
114	    if (data) {
115	        free(data->srcA);
116	        free(data->srcB);
117	        free(data->expected);
118	        free(data);
119	    }
120	    return EXIT_SUCCESS;
121	}
122	
123	DECLARE_TEST(neon_rot_u8x16, "NEON variant: uint8x16 (16-lane byte) 2-src load + rotating ALU + store/reload — width-vs-lane probe")
124	    .test_init    = neon_rot_u8x16_init,
125	    .test_run     = neon_rot_u8x16_run,
126	    .test_cleanup = neon_rot_u8x16_cleanup,
127	    .quality_level = TEST_QUALITY_PROD,
128	END_DECLARE_TEST
