1	/**
2	 * @copyright
3	 * Copyright 2025 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b movbe_sve
7	 * @parblock
8	 * SVE port of movbe: byte-swap followed by another byte-swap restoring
9	 * the original order, on SVE vector lanes. Each 32-bit element's bytes
10	 * are permuted by svtbl with the [3,2,1,0] index table (bit-exact vs
11	 * __builtin_bswap32, 50k random vectors verified); the swapped value is
12	 * stored and reloaded through svst1/svld1 (the vector store->load path
13	 * that mirrors the scalar trigger recipe's reload). Input is random
14	 * (framework RNG at init), reused per iteration exactly as the original.
15	 * @endparblock
16	 */
17	
18	#include "sandstone.h"
19	#include <cstdint>
20	#include <cstring>
21	
22	#if defined(__aarch64__)
23	#include <arm_sve.h>
24	#include <sys/auxv.h>
25	
26	#ifndef HWCAP_SVE
27	#define HWCAP_SVE (1 << 22)
28	#endif
29	#endif
30	
31	#define MOVBE_BUFFER_SIZE (1 << 14)
32	
33	struct movbe_sve_data {
34	    uint32_t *input;
35	    uint32_t *swapped;
36	};
37	
38	static int movbe_sve_init(struct test *test)
39	{
40	#if defined(__aarch64__)
41	    unsigned long hwcap = getauxval(AT_HWCAP);
42	    if ((hwcap & HWCAP_SVE) == 0) {
43	        log_skip(CpuNotSupportedSkipCategory,
44	                 "to be implemented (placeholder): ARM SVE required for movbe_sve");
45	        return EXIT_SKIP;
46	    }
47	#endif
48	    auto *data = (movbe_sve_data *)malloc(sizeof(movbe_sve_data));
49	    data->input = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
50	    data->swapped = (uint32_t *)aligned_alloc_safe(64, MOVBE_BUFFER_SIZE * sizeof(uint32_t));
51	
52	    for (size_t i = 0; i < MOVBE_BUFFER_SIZE; ++i) {
53	        data->input[i] = random32();
54	    }
55	
56	    test->data = data;
57	    return EXIT_SUCCESS;
58	}
59	
60	#if defined(__aarch64__)
61	static int movbe_sve_run(struct test *test, int cpu)
62	{
63	    (void)cpu;
64	    auto *data = (movbe_sve_data *)test->data;
65	
66	    /* bswap32 的 svtbl 索引: 每元素 [3,2,1,0] */
67	    static const uint8_t idx4[4] = {3, 2, 1, 0};
68	
69	    const int lanes = svcntw();
70	    uint8_t vidx_bytes[64];
71	    for (int i = 0; i < lanes && i < 16; ++i)
72	        for (int b = 0; b < 4; ++b)
73	            vidx_bytes[i * 4 + b] = (uint8_t)(i * 4 + idx4[b]);
74	    svbool_t pg_batch = svwhilelt_b8((uint64_t)0, (uint64_t)(lanes < 16 ? lanes * 4 : 64));
75	    svuint8_t vidx = svld1_u8(pg_batch, vidx_bytes);
76	
77	    TEST_LOOP(test, 1 << 13) {
78	        for (size_t base = 0; base < MOVBE_BUFFER_SIZE; base += lanes) {
79	            int n = (MOVBE_BUFFER_SIZE - base < (size_t)lanes) ? (int)(MOVBE_BUFFER_SIZE - base) : lanes;
80	            svbool_t pg = svwhilelt_b8((uint64_t)0, (uint64_t)(n * 4));
81	
82	            /* 直接堆访存 (无栈中转): 修复版 —— 原版被测路径是
83	             * 堆 store(swapped) 后紧跟堆 reload, 栈中转会改变被测微操作序列 */
84	            uint8_t in_bytes[64];
85	            memcpy(in_bytes, data->input + base, n * 4);
86	            svuint8_t vswapped = svtbl_u8(svld1_u8(pg, in_bytes), vidx);
87	
88	            /* ★ 堆 store: svst1 直接写 swapped 堆缓冲区 */
89	            svst1_u8(pg, (uint8_t *)(data->swapped + base), vswapped);
90	
91	            /* ★ 堆 reload: svld1 直接从 swapped 读回 (被测的 store→load 转发路径) */
92	            svuint8_t reloaded = svld1_u8(pg, (const uint8_t *)(data->swapped + base));
93	
94	            /* 再交换一次还原 (同一索引表, svtbl 可逆) */
95	            svuint8_t vrestored = svtbl_u8(reloaded, vidx);
96	            uint8_t out_bytes[64];
97	            svst1_u8(pg, out_bytes, vrestored);
98	
99	            /* 校验: 还原值 == 输入值 */
100	            uint32_t restored[16];
101	            memcpy(restored, out_bytes, n * 4);
102	            for (int i = 0; i < n; ++i) {
103	                if (restored[i] != data->input[base + i]) {
104	                    report_fail_msg("MovBE-SVE: Round-trip failed at index %u",
105	                                    (unsigned)(base + i));
106	                }
107	            }
108	        }
109	    }
110	
111	    return EXIT_SUCCESS;
112	}
113	#else
114	static int movbe_sve_run(struct test *test, int cpu)
115	{
116	    (void)test; (void)cpu;
117	    log_skip(CpuNotSupportedSkipCategory,
118	             "to be implemented (placeholder): ARM SVE required for movbe_sve");
119	    return EXIT_SKIP;
120	}
121	#endif
122	
123	static int movbe_sve_cleanup(struct test *test)
124	{
125	    auto *data = (movbe_sve_data *)test->data;
126	    if (data) {
127	        free(data->input);
128	        free(data->swapped);
129	        free(data);
130	    }
131	    return EXIT_SUCCESS;
132	}
133	
134	DECLARE_TEST(movbe_sve,
135	             "SVE byte-swap round-trip: svtbl [3,2,1,0] permutation + vector "
136	             "store/reload on svst1/svld1 lanes (port of movbe)")
137	    .test_init = movbe_sve_init,
138	    .test_run = movbe_sve_run,
139	    .test_cleanup = movbe_sve_cleanup,
140	    .quality_level = TEST_QUALITY_PROD,
141	END_DECLARE_TEST
