1	/**
2	 * @copyright
3	 * Copyright 2025 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b mrn_nuke_sve
7	 * @parblock
8	 * SVE port of mrn_nuke: array copy through a temp buffer on vector lanes —
9	 * svst1-to-temp then svld1-from-temp store->load forwarding dependency
10	 * stressing the memory-renaming logic.
11	 * @endparblock
12	 */
13	
14	#include "sandstone.h"
15	#include <cstdint>
16	#include <cstring>
17	#include <cstdlib>
18	
19	#if defined(__aarch64__)
20	#include <arm_sve.h>
21	#include <sys/auxv.h>
22	
23	#ifndef HWCAP_SVE
24	#define HWCAP_SVE (1 << 22)
25	#endif
26	#endif
27	
28	#define MRN_NUKE_SVE_COUNT 1024
29	
30	struct MrnNukeSveData {
31	    uint64_t *src;
