5	 *
6	 * @test @b arm0102_kreg_mask_sve
7	 * @parblock
8	 * SVE port of arm0102_kreg_mask (SDC trigger-format variant of kreg7/8:
9	 * 2-source vector loads + rotating compare-mask expansion
10	 * eq/gt/eq-u/tst + back-to-back store→reload→store amplifier).
11	 * The SVE version keeps the verified core-179 trigger recipe structure
12	 * but moves the data path to SVE: asm-guaranteed ldr z for the two source
13	 * loads, predicate compares (svcmpeq/svcmpgt) + svsel for the mask
14	 * expansion (the real SVE equivalent of the kreg semantics), and
15	 * back-to-back str z → ldr z → str z as the amplifier.
16	 * Golden precomputed in init on the same SVE units; memcmp in cold path.
17	 * @endparblock
18	 */
19	
20	#include "sandstone.h"
21	#include <cstdint>
22	#include <cstring>
23	#include <cstdlib>
24	
25	#if defined(__aarch64__)
26	#include <arm_sve.h>
27	#include <sys/auxv.h>
28	
29	#ifndef HWCAP_SVE
30	#define HWCAP_SVE (1 << 22)
31	#endif
32	#endif
33	
34	#define ARM0102_KREG_MASK_SVE_COUNT 1024   /* elements per buffer (uint32) */
35	
36	struct Arm0102KregMaskSveData {
37	    uint32_t *srcA;
38	    uint32_t *srcB;
39	    uint32_t *expected;
40	};
41	
42	#if defined(__aarch64__)
43	
44	/* 4-lane (16B) 语义的存/取 —— 与子块谓词 pg4 严格一致。
45	 * 注意不能用 svptrue_b32(): VL=256 时它是 8 lane/32B, 会越界写
46	 * 4 元素子块后面的内存 (851 次循环后堆元数据被砸穿 → double free,
47	 * 批次 1 调试时抓到的 bug)。 */
48	#define KREG_SVE_SUBLANES 4
49	
50	static inline void store_vec_sve(void *addr, svuint32_t val) {
51	    svbool_t pg = svwhilelt_b32((uint64_t)0, (uint64_t)KREG_SVE_SUBLANES);
52	    svst1_u32(pg, static_cast<uint32_t *>(addr), val);
53	}
54	
55	static inline svuint32_t load_vec_sve(const void *addr) {
56	    svuint32_t res;
57	    /* asm 保证的加载 (core-179 配方要求, 与原版 ldr q 对应);
58	     * SVE ldr z 按 VL 全宽载, 后续所有计算/存储都用 pg4 截断 */
59	    __asm__ volatile ("ldr %0, [%1]" : "=w"(res) : "r"(addr) : "memory");
60	    return res;
61	}
62	
63	/* 旋转比较掩码扩展: i%4 → eq/gt(signed)/eq-u/tst —— 谓词 + svsel (真 kreg 语义) */
64	static inline svuint32_t kreg_expand_rotating(svbool_t pg, svuint32_t a, svuint32_t b, int i) {
65	    switch (i % 4) {
66	        case 0: {  /* eq (signed reinterpret) */
67	            svint32_t sa = svreinterpret_s32_u32(a), sb = svreinterpret_s32_u32(b);
68	            svbool_t p = svcmpeq_s32(pg, sa, sb);
69	            return svsel_u32(p, svdup_u32(0xFFFFFFFFu), svdup_u32(0));
70	        }
71	        case 1: {  /* gt (signed) */
72	            svint32_t sa = svreinterpret_s32_u32(a), sb = svreinterpret_s32_u32(b);
73	            svbool_t p = svcmpgt_s32(pg, sa, sb);
74	            return svsel_u32(p, svdup_u32(0xFFFFFFFFu), svdup_u32(0));
75	        }
76	        case 2: {  /* eq-u */
77	            svbool_t p = svcmpeq_u32(pg, a, b);
78	            return svsel_u32(p, svdup_u32(0xFFFFFFFFu), svdup_u32(0));
79	        }
80	        default: { /* tst: (a & b) != 0 */
81	            svbool_t p = svcmpne_n_u32(pg, svand_u32_x(pg, a, b), 0);
82	            return svsel_u32(p, svdup_u32(0xFFFFFFFFu), svdup_u32(0));
83	        }
84	    }
85	}
86	
87	static int arm0102_kreg_mask_sve_init(struct test *test) {
88	    unsigned long hwcap = getauxval(AT_HWCAP);
89	    if ((hwcap & HWCAP_SVE) == 0) {
90	        log_skip(CpuNotSupportedSkipCategory,
91	                 "to be implemented (placeholder): ARM SVE required for arm0102_kreg_mask_sve");
92	        return EXIT_SKIP;
93	    }
94	
95	    auto *data = static_cast<Arm0102KregMaskSveData *>(malloc(sizeof(Arm0102KregMaskSveData)));
96	    data->srcA = static_cast<uint32_t *>(aligned_alloc(64, ARM0102_KREG_MASK_SVE_COUNT * sizeof(uint32_t)));
97	    data->srcB = static_cast<uint32_t *>(aligned_alloc(64, ARM0102_KREG_MASK_SVE_COUNT * sizeof(uint32_t)));
98	    data->expected = static_cast<uint32_t *>(aligned_alloc(64, ARM0102_KREG_MASK_SVE_COUNT * sizeof(uint32_t)));
99	
100	    memset_random(data->srcA, ARM0102_KREG_MASK_SVE_COUNT * sizeof(uint32_t));
101	    memset_random(data->srcB, ARM0102_KREG_MASK_SVE_COUNT * sizeof(uint32_t));
102	
103	    /* golden: 同一旋转组合, 在相同 SVE 单元上预计算 */
104	    svbool_t pg = svptrue_b32();
105	    const int lanes = svcntw();
106	    for (int base = 0; base < ARM0102_KREG_MASK_SVE_COUNT; base += lanes) {
107	        int n = (ARM0102_KREG_MASK_SVE_COUNT - base < lanes) ? (ARM0102_KREG_MASK_SVE_COUNT - base) : lanes;
108	        svbool_t pgn = svwhilelt_b32((uint64_t)0, (uint64_t)n);
109	        /* 与 run 完全相同的 4 元素子块结构 + 相位 (base+sub)%4 */
110	        for (int sub = 0; sub < n; sub += 4) {
111	            int phase = (base + sub) % 4;
112	            /* 单 lane 组: 用标量嵌入向量 */
113	            uint32_t av[8], bv[8], ov[8];
114	            for (int k = 0; k < 4 && sub + k < n; ++k) {
115	                av[k] = data->srcA[base + sub + k];
116	                bv[k] = data->srcB[base + sub + k];
117	            }
118	            svbool_t pg4 = svwhilelt_b32((uint64_t)0, (uint64_t)4);
119	            svuint32_t va = svld1_u32(pg4, av), vb = svld1_u32(pg4, bv);
120	            svuint32_t res = kreg_expand_rotating(pg4, va, vb, phase);
121	            svst1_u32(pg4, ov, res);
122	            for (int k = 0; k < 4 && sub + k < n; ++k)
123	                data->expected[base + sub + k] = ov[k];
124	        }
125	    }
126	
127	    test->data = data;
128	    return EXIT_SUCCESS;
129	}
130	
131	static int arm0102_kreg_mask_sve_run(struct test *test, int cpu) {
132	    auto *data = static_cast<Arm0102KregMaskSveData *>(test->data);
133	
134	    uint32_t *temp = static_cast<uint32_t *>(aligned_alloc(64, ARM0102_KREG_MASK_SVE_COUNT * sizeof(uint32_t)));
135	    uint32_t *dst  = static_cast<uint32_t *>(aligned_alloc(64, ARM0102_KREG_MASK_SVE_COUNT * sizeof(uint32_t)));
136	
137	    TEST_LOOP(test, 1 << 13) {
138	        /* 与 golden 完全相同的 4 元素子块结构: 每 SVE 向量批内按 4 元素子块,
139	         * 相位 = (base+sub) % 4 (与 init 的 golden 循环逐字一致) */
140	        for (int base = 0; base < ARM0102_KREG_MASK_SVE_COUNT; base += svcntw()) {
141	            int n = (ARM0102_KREG_MASK_SVE_COUNT - base < svcntw()) ? (ARM0102_KREG_MASK_SVE_COUNT - base) : svcntw();
142	            for (int sub = 0; sub < n; sub += 4) {
143	                /* 2 源加载: asm 保证的 ldr z (SVE 版配方核心) */
144	                svuint32_t a = load_vec_sve(data->srcA + base + sub);   /* ldr z — source 1 */
145	                svuint32_t b = load_vec_sve(data->srcB + base + sub);   /* ldr z — source 2 */
146	                svbool_t pg4 = svwhilelt_b32((uint64_t)0, (uint64_t)4);
147	
148	                /* 载荷: 谓词比较掩码扩展 + svsel (相位与 golden 一致) */
149	                svuint32_t res = kreg_expand_rotating(pg4, a, b, base + sub);
150	
151	                /* 放大器: str z -> ldr z -> str z */
152	                store_vec_sve(temp + base + sub, res);
153	                store_vec_sve(dst + base + sub, load_vec_sve(temp + base + sub));
154	            }
155	        }
156	
157	        if (memcmp(dst, data->expected, ARM0102_KREG_MASK_SVE_COUNT * sizeof(uint32_t)) != 0) {
158	            report_fail_msg("arm0102_kreg_mask_sve data miscompare");
159	        }
160	    }
161	
162	    free(dst);
163	    free(temp);
164	    return EXIT_SUCCESS;
165	}
166	
167	static int arm0102_kreg_mask_sve_cleanup(struct test *test) {
168	    auto *data = static_cast<Arm0102KregMaskSveData *>(test->data);
169	    if (data) {
170	        free(data->srcA);
171	        free(data->srcB);
172	        free(data->expected);
173	        free(data);
174	    }
175	    return EXIT_SUCCESS;
176	}
177	
178	#else
179	
180	static int arm0102_kreg_mask_sve_init(struct test *test) {
181	    (void)test;
182	    log_skip(CpuNotSupportedSkipCategory,
183	             "to be implemented (placeholder): ARM SVE required for arm0102_kreg_mask_sve");
184	    return EXIT_SKIP;
185	}
186	static int arm0102_kreg_mask_sve_run(struct test *test, int cpu) {
187	    (void)test; (void)cpu;
188	    return EXIT_SKIP;
189	}
190	static int arm0102_kreg_mask_sve_cleanup(struct test *test) {
191	    (void)test;
192	    return EXIT_SUCCESS;
193	}
194	
195	#endif
196	
197	DECLARE_TEST(arm0102_kreg_mask_sve,
198	             "SVE port of arm-0102 kreg mask variant: 2-src ldr z + rotating predicate compare-mask expand (eq/gt/eq-u/tst via svsel) + str z/ldr z/str z amplifier")
199	    .test_init    = arm0102_kreg_mask_sve_init,
200	    .test_run     = arm0102_kreg_mask_sve_run,
201	    .test_cleanup = arm0102_kreg_mask_sve_cleanup,
202	    .quality_level = TEST_QUALITY_PROD,
203	END_DECLARE_TEST
