#define HWCAP_SVE (1 << 22)
#endif
#endif

#define MOVBE_L1D_SVE_BUFFER_SIZE (1 << 14)

struct MovbeL1dL2SveData {
    uint32_t *input;
    uint32_t *swapped;
};

static int movbe_l1d_sve_init(struct test *test)
{
#if defined(__aarch64__)
